    if(!$last.src.breaks){if(!$sb.Count-or!$ob.Count){throw 'Resting bottle missing in a world'};$d=[Math]::Sqrt([Math]::Pow($sb[0].position[0]-$ob[0].position[0],2)+[Math]::Pow($sb[0].position[1]-$ob[0].position[1],2)+[Math]::Pow($sb[0].position[2]-$ob[0].position[2],2))
     $row.restGap=[Math]::Round($d,3);$row.checks.Add("Resting bottles $($row.restGap) m apart");if($d-gt.75){throw 'Resting bottles disagree between the worlds'}}
    else{$row.checks.Add('Both copies broken')}}
   $row.passed=$true
  }catch{if($_.Exception.Message-ne'farreach-done'){$row.failure=$_.Exception.Message}}
  foreach($c in $capture,$peerCapture){if($c){try{if(!$c.HasExited){Stop-Process -Id $c.Id}}catch{}}}
  try{Restore $key;$row.restored=$true}catch{$row.restored=$false;$row.failure=(("$($row.failure); restore: "+$_.Exception.Message)).TrimStart('; ')}
  $rows.Add([pscustomobject]$row);Save "$out/$key.json" ([pscustomobject]$row)
  if(!$row.restored){throw "Fixture restore failed after $key"}
 }}
 $dirty=$false
}catch{$failure=$_.Exception.Message;Save "$out/failure.json" @{message=$failure;stack=$_.ScriptStackTrace}}finally{
 if($owned){
  if($dirty){try{Restore 'final'}catch{$failure=($failure+'; restore: '+$_.Exception.Message).TrimStart('; ')}}else{Disarm}
  $errors=[Collections.Generic.List[string]]::new()
  try{foreach($f in(Get-Content "$root/work/movement-integration/protected-save-hashes-before-v4.json" -Raw|ConvertFrom-Json)){if((Get-FileHash $f.Path).Hash-ne$f.Hash){$errors.Add('Protected file changed')}}}catch{$errors.Add($_.Exception.Message)}
  foreach($r in 'host','client'){try{$s=S $r;if($s.localGameLogicState-ne1-or!$s.remoteFresh-or(Q $r '--health' 1).current-ne56){$errors.Add("$r gameplay/transport/health not restored")}}catch{$errors.Add("$r status unavailable")}}
  if(Test-Path -LiteralPath $out){
   Save "$out/restoration.json" @{passed=(!$errors.Count);errors=@($errors)}
   $bad=@($rows|Where-Object {!$_.passed});if(!$failure-and$bad.Count){$failure="$($bad.Count) case(s) failed: "+(($bad|ForEach-Object {"$($_.source)-$($_.case): $($_.failure)"})-join ' | ')}
   if($errors.Count-and!$failure){$failure=$errors-join '; '}
   Save "$out/result.json" ([ordered]@{passed=(!$failure);failure=$failure;cases=@($rows);scope='Pickup, food and held-object gestures (1214j, 1214ea): native LootObject47 drives the partner use reach toward the item; a held movable (HoldObject 49) is pinned to the partner hand and its throw or placement followed; both source roles, product controller; fixture restored after every case.'})
  }
  [ordered]@{pid=$PID;operation='Gestures1261';take=$Take;ended=(Get-Date).ToString('o');state='finished'}|ConvertTo-Json|Set-Content "$root/work/movement-integration/native-operation-owner.json"
  $mutex.ReleaseMutex()
 };$mutex.Dispose()
}
if($failure){throw $failure};"PASS_GESTURES $($rows.Count) cases"
